/** HazRob one-experiment XLSX/PDF report. The chemical catalogue has no legacy 144-row cap. */
public final class ReportExporter {
    private static final int GRID_COLS=15;
    private static final int GRID_ROWS=13;
    private static final int GRID_CAPACITY=GRID_COLS*GRID_ROWS; // 195/page; 780 on the requested four overview pages.
    private static final int MIN_OVERVIEW_PAGES=4;
    private ReportExporter(){}

    public static void writeXlsx(OutputStream out,ExperimentQueries.Record r)throws Exception{writeXlsx(out,r,null);}
    public static void writeXlsx(OutputStream out,ExperimentQueries.Record r,ChemicalRepository chemicals)throws Exception{
        if(r==null)throw new IllegalArgumentException("record");
        ZipOutputStream z=new ZipOutputStream(out);
        entry(z,"[Content_Types].xml",contentTypes());
        entry(z,"_rels/.rels","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
        entry(z,"xl/workbook.xml",workbook());entry(z,"xl/_rels/workbook.xml.rels",workbookRels());entry(z,"xl/styles.xml",styles());
        entry(z,"xl/worksheets/sheet1.xml",summarySheet(r,chemicals));entry(z,"xl/worksheets/sheet2.xml",physicalSheet(r));entry(z,"xl/worksheets/sheet3.xml",mqSheet(r));entry(z,"xl/worksheets/sheet4.xml",chemicalSheet(r,chemicals));
        z.finish();z.flush();
    }
    public static void writeXlsx(OutputStream out,List<ExperimentQueries.Record> rows)throws Exception{if(rows==null||rows.isEmpty())throw new IllegalArgumentException("no experiment");writeXlsx(out,rows.get(0),null);}

    public static void writePdf(OutputStream out,ExperimentQueries.Record r)throws Exception{writePdf(out,r,null);}
    public static void writePdf(OutputStream out,ExperimentQueries.Record r,ChemicalRepository chemicals)throws Exception{
        if(r==null)throw new IllegalArgumentException("record");
        PdfDocument pdf=new PdfDocument();JSONObject d=json(r.payload),a=json(r.analytics);PdfReport p=new PdfReport(pdf,chemicals);
        p.summary(r,d,a);p.physical(d);p.mq(d);p.overview(a);p.chemicals(a);p.finish();pdf.writeTo(out);pdf.close();
    }
    public static void writePdf(OutputStream out,List<ExperimentQueries.Record> rows)throws Exception{if(rows==null||rows.isEmpty())throw new IllegalArgumentException("no experiment");writePdf(out,rows.get(0),null);}

    private static String contentTypes(){return "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet2.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet3.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet4.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>";}
    private static String workbook(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"ملخص الفحص\" sheetId=\"1\" r:id=\"rId1\"/><sheet name=\"القياسات الفيزيائية\" sheetId=\"2\" r:id=\"rId2\"/><sheet name=\"قراءات MQ\" sheetId=\"3\" r:id=\"rId3\"/><sheet name=\"المركبات والنتائج\" sheetId=\"4\" r:id=\"rId4\"/></sheets></workbook>";}
    private static String workbookRels(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/><Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet2.xml\"/><Relationship Id=\"rId3\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet3.xml\"/><Relationship Id=\"rId4\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet4.xml\"/><Relationship Id=\"rId5\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>";}
    private static String styles(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><fonts count=\"2\"><font><sz val=\"10\"/><name val=\"Arial\"/></font><font><b/><color rgb=\"FFFFFFFF\"/><sz val=\"10\"/><name val=\"Arial\"/></font></fonts><fills count=\"9\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF263238\"/></patternFill></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF1B5E20\"/></patternFill></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF43A047\"/></patternFill></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FFF9A825\"/></patternFill></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FFEF6C00\"/></patternFill></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FFC62828\"/></patternFill></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF90CAF9\"/></patternFill></fill></fills><borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"8\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"2\" borderId=\"0\" xfId=\"0\" applyFill=\"1\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"3\" borderId=\"0\" xfId=\"0\" applyFill=\"1\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"4\" borderId=\"0\" xfId=\"0\" applyFill=\"1\"/><xf numFmtId=\"0\" fontId=\"0\" fillId=\"5\" borderId=\"0\" xfId=\"0\" applyFill=\"1\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"6\" borderId=\"0\" xfId=\"0\" applyFill=\"1\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"7\" borderId=\"0\" xfId=\"0\" applyFill=\"1\"/><xf numFmtId=\"0\" fontId=\"0\" fillId=\"8\" borderId=\"0\" xfId=\"0\" applyFill=\"1\"/></cellXfs></styleSheet>";}

    private static String summarySheet(ExperimentQueries.Record r,ChemicalRepository chemicals){JSONObject d=json(r.payload),m=d.optJSONObject("measurement"),e=env(d),a=json(r.analytics);StringBuilder s=sheetStart();row(s,1,new String[]{"HazRob v0.6.1 - تقرير فحص","القيمة"},1);int x=2;row(s,x++,new String[]{"رقم التجربة",String.valueOf(r.id)},0);row(s,x++,new String[]{"تاريخ الفحص UTC",n(r.ts)},0);row(s,x++,new String[]{"البروتوكول",n(r.protocol)},0);row(s,x++,new String[]{"الحالة المرجعية",r.approved?"معتمدة":"غير معتمدة"},0);row(s,x++,new String[]{"Firmware",d.optString("firmware","إصدار قديم غير معرّف")},0);row(s,x++,new String[]{"API",String.valueOf(d.optInt("api_version",1))},0);row(s,x++,new String[]{"حالة دورة MQ",m==null?"":m.optString("state","")},0);row(s,x++,new String[]{"نوع الحساس البيئي",e==null?"غير مكتشف":e.optString("type",e.optString("sensor","BME280"))},0);if(chemicals!=null)row(s,x++,new String[]{"مواد قاعدة المعرفة",String.valueOf(chemicals.count())},0);row(s,x++,new String[]{"نتائج التحليل ذات الدليل",String.valueOf(resultCount(a))},0);row(s,x++,new String[]{"ملاحظة","تعرض خريطة PDF جميع مواد قاعدة المعرفة، وتلون فقط المواد التي لها دليل حسي/تحليلي. الأزرق دليل غير كمي؛ ألوان الخطورة تستخدم فقط عند توفر PPM كمي وتفسير خطر صالح."},0);return sheetEnd(s);}
    private static String physicalSheet(ExperimentQueries.Record r){JSONObject d=json(r.payload),e=env(d);StringBuilder s=sheetStart();row(s,1,new String[]{"#","القياس","القيمة","الوحدة","المصدر / الحالة"},1);for(int i=0;i<PhysicalCatalog.COUNT;i++){String value="",source="غير مركب";if(e!=null&&e.optBoolean("ok",false)){String type=e.optString("type",e.optString("sensor","BME280"));if(i==0){value=num(e,"temperature");source=type;}else if(i==1){value=num(e,"humidity");source=value.isEmpty()?"غير متاحة في "+type:type;}else if(i==2){value=num(e,"pressure");source=type;}else if(i==14){double p=e.optDouble("pressure",Double.NaN);if(Double.isFinite(p)&&p>0){value=fmt(44330.0*(1.0-Math.pow(p/1013.25,0.1903)));source="مشتق من الضغط @ 1013.25 hPa";}}}row(s,i+2,new String[]{String.valueOf(i+1),PhysicalCatalog.NAMES_AR[i],value,PhysicalCatalog.UNITS[i],source},0);}return sheetEnd(s);}
    private static String mqSheet(ExperimentQueries.Record r){JSONObject d=json(r.payload),m=d.optJSONObject("measurement");boolean averaged=m!=null&&"ready".equalsIgnoreCase(m.optString("state"))&&m.optJSONObject("mq")!=null;JSONObject src=averaged?m.optJSONObject("mq"):d.optJSONObject("mq");StringBuilder s=sheetStart();row(s,1,new String[]{"الحساس","الحالة","Raw","ADC V","AO V","Rs","Rs/R0","متوسط دورة مكتملة"},1);int rr=2;if(src!=null)for(String key:RobotTelemetry.MQ_KEYS){JSONObject q=src.optJSONObject(key);if(q==null)continue;String status=q.has("status")?q.optString("status",""):(q.has("valid")?(q.optBoolean("valid")?"صالح":"غير صالح"):"");row(s,rr++,new String[]{key.toUpperCase(Locale.US),status,num(q,"raw"),num(q,"adc"),num(q,"ao"),num(q,"rs"),num(q,"ratio"),averaged?"نعم":"لا"},0);}return sheetEnd(s);}

    private static String chemicalSheet(ExperimentQueries.Record r,ChemicalRepository chemicals){JSONObject a=json(r.analytics);ResultIndex ix=new ResultIndex(a);StringBuilder s=sheetStart();row(s,1,new String[]{"#","المركب","CAS","الصيغة","حالة الدليل","PPM","التوافق %","الثقة","الخطر","كمي","المساهمون","ملاحظة النموذج"},1);int rr=2,index=0;if(chemicals!=null){List<ChemicalRepository.Chemical> catalog=chemicals.search("",5000);for(ChemicalRepository.Chemical c:catalog){index++;JSONObject q=ix.forChemical(c);boolean evidence=hasEvidence(q),quant=evidence&&q.optBoolean("quantitative",false);int risk=quant?q.optInt("risk",0):0;int style=evidence?(risk>0?riskStyle(risk):7):0;String[] v={String.valueOf(index),chemicalName(c),n(c.cas),n(c.formula),evidence?(quant?"قياس كمي":"دليل/بصمة"):"لا دليل",quant?num(q,"ppm"):"",evidence?num(q,"agreement"):"",evidence?stars(q.optInt("confidence",0)):"—",risk>0?riskName(risk):"غير متاح",quant?"نعم":"لا",evidence?String.valueOf(q.optInt("contributors",0)):"0",evidence?q.optString("note",""):""};row(s,rr++,v,style);}}else{JSONArray arr=results(a);for(int i=0;i<arr.length();i++){JSONObject q=arr.optJSONObject(i);if(!hasEvidence(q))continue;index++;boolean quant=q.optBoolean("quantitative",false);int risk=quant?q.optInt("risk",0):0;row(s,rr++,new String[]{String.valueOf(index),resultName(q),q.optString("cas",""),q.optString("formula",""),quant?"قياس كمي":"دليل/بصمة",quant?num(q,"ppm"):"",num(q,"agreement"),stars(q.optInt("confidence",0)),risk>0?riskName(risk):"غير متاح",quant?"نعم":"لا",String.valueOf(q.optInt("contributors",0)),q.optString("note","")},risk>0?riskStyle(risk):7);}}if(index==0)row(s,2,new String[]{"—","لا توجد مواد متاحة","","","","","","","","","",""},0);return sheetEnd(s);}

    private static final class ResultIndex{
        final Map<Long,JSONObject> byUid=new HashMap<>();final Map<Integer,JSONObject> byLegacy=new HashMap<>();final Map<String,JSONObject> byCas=new HashMap<>();
        ResultIndex(JSONObject a){JSONArray arr=results(a);for(int i=0;i<arr.length();i++){JSONObject q=arr.optJSONObject(i);if(!hasEvidence(q))continue;if(q.has("chemical_uid"))byUid.put(q.optLong("chemical_uid"),q);if(q.has("legacy_id"))byLegacy.put(q.optInt("legacy_id"),q);else if(q.has("chemical_id"))byLegacy.put(q.optInt("chemical_id"),q);String cas=q.optString("cas","").trim();if(!cas.isEmpty())byCas.put(cas,q);}}
        JSONObject forChemical(ChemicalRepository.Chemical c){JSONObject q=byUid.get(c.uid);if(q!=null)return q;if(c.legacyId!=null){q=byLegacy.get(c.legacyId);if(q!=null)return q;}if(c.cas!=null&&!c.cas.trim().isEmpty())return byCas.get(c.cas.trim());return null;}
    }

    private static final class PdfReport {
        final PdfDocument pdf;final ChemicalRepository chemicals;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);PdfDocument.Page page;Canvas c;int pageNo=0;float y;
        PdfReport(PdfDocument pdf,ChemicalRepository chemicals){this.pdf=pdf;this.chemicals=chemicals;p.setTypeface(android.graphics.Typeface.create("sans",android.graphics.Typeface.NORMAL));}
        void newPage(String title){if(page!=null)pdf.finishPage(page);page=pdf.startPage(new PdfDocument.PageInfo.Builder(842,595,++pageNo).create());c=page.getCanvas();c.drawColor(Color.WHITE);p.setTextAlign(Paint.Align.RIGHT);p.setColor(0xFF0D47A1);p.setTextSize(17);c.drawText(title,812,30,p);p.setTextAlign(Paint.Align.LEFT);p.setColor(Color.DKGRAY);p.setTextSize(8);c.drawText("HazRob v0.6.1 • page "+pageNo,30,30,p);y=52;}
        void summary(ExperimentQueries.Record r,JSONObject d,JSONObject a){newPage("تقرير فحص HazRob");lineR("رقم التجربة: "+r.id);lineR("تاريخ الفحص UTC: "+n(r.ts));lineR("البروتوكول: "+n(r.protocol));lineR("الحالة المرجعية: "+(r.approved?"معتمدة":"غير معتمدة"));lineR("Firmware: "+d.optString("firmware","إصدار قديم غير معرّف")+"   API: "+d.optInt("api_version",1));JSONObject m=d.optJSONObject("measurement");if(m!=null)lineR("دورة MQ: "+m.optString("state","")+"   العينات "+m.optInt("samples1",0)+"/"+m.optInt("samples2",0)+"/"+m.optInt("samples3",0));JSONObject e=env(d);if(e!=null&&e.optBoolean("ok",false))lineR("الحساس البيئي: "+e.optString("type",e.optString("sensor","BME280"))+"   "+num(e,"temperature")+" °C   "+num(e,"humidity")+" %RH   "+num(e,"pressure")+" hPa");if(chemicals!=null)lineR("مواد قاعدة المعرفة: "+chemicals.count());lineR("نتائج التحليل ذات الدليل: "+resultCount(a));y+=8;note("خريطة المواد التالية موزعة على أربع صفحات بواقع 15 عمودًا × 13 صفًا في الصفحة. الرمادي يعني لا يوجد دليل في هذا القياس، والأزرق يعني دليل/بصمة غير كمية. لا تستخدم ألوان الخطورة إلا عندما تتوفر قيمة PPM كمية وتفسير خطر صالح.");}
        void physical(JSONObject d){newPage("القياسات الفيزيائية والبيئية");header(new String[]{"#","القياس","القيمة","الوحدة","المصدر / الحالة"},new float[]{30,260,120,80,260});JSONObject e=env(d);for(int i=0;i<PhysicalCatalog.COUNT;i++){String value="",source="غير مركب";if(e!=null&&e.optBoolean("ok",false)){String type=e.optString("type",e.optString("sensor","BME280"));if(i==0){value=num(e,"temperature");source=type;}else if(i==1){value=num(e,"humidity");source=value.isEmpty()?"غير متاحة في "+type:type;}else if(i==2){value=num(e,"pressure");source=type;}else if(i==14){double pr=e.optDouble("pressure",Double.NaN);if(Double.isFinite(pr)&&pr>0){value=fmt(44330.0*(1.0-Math.pow(pr/1013.25,0.1903)));source="مشتق من الضغط";}}}tableRow(new String[]{String.valueOf(i+1),PhysicalCatalog.NAMES_AR[i],value,PhysicalCatalog.UNITS[i],source},new float[]{30,260,120,80,260},0);}}
        void mq(JSONObject d){newPage("قراءات حساسات MQ");header(new String[]{"الحساس","الحالة","Raw","Vadc","Vao","Rs","Rs/R0"},new float[]{90,120,80,100,100,120,120});JSONObject m=d.optJSONObject("measurement");JSONObject src=m!=null&&"ready".equalsIgnoreCase(m.optString("state"))&&m.optJSONObject("mq")!=null?m.optJSONObject("mq"):d.optJSONObject("mq");if(src!=null)for(String key:RobotTelemetry.MQ_KEYS){JSONObject q=src.optJSONObject(key);if(q==null)continue;String st=q.has("status")?q.optString("status",""):(q.optBoolean("valid",false)?"صالح":"غير صالح");tableRow(new String[]{key.toUpperCase(Locale.US),st,num(q,"raw"),num(q,"adc"),num(q,"ao"),num(q,"rs"),num(q,"ratio")},new float[]{90,120,80,100,100,120,120},0);}}

        void overview(JSONObject a){List<ChemicalRepository.Chemical> catalog=chemicals==null?new ArrayList<>():chemicals.search("",5000);ResultIndex ix=new ResultIndex(a);if(catalog.isEmpty()){overviewResultsOnly(a);return;}int pages=Math.max(MIN_OVERVIEW_PAGES,(catalog.size()+GRID_CAPACITY-1)/GRID_CAPACITY);for(int pg=0;pg<pages;pg++){int start=pg*GRID_CAPACITY,end=Math.min(catalog.size(),start+GRID_CAPACITY);newPage("خريطة مواد قاعدة المعرفة • "+(pg+1)+"/"+pages+" • "+(start+1)+"–"+end);drawLegend();float left=20f,top=82f,cw=802f/GRID_COLS,ch=480f/GRID_ROWS;for(int slot=0;slot<GRID_CAPACITY;slot++){int idx=start+slot;int row=slot/GRID_COLS,col=slot%GRID_COLS;float x=left+col*cw,yy=top+row*ch;if(idx>=catalog.size()){drawEmptyCell(x,yy,cw,ch);continue;}ChemicalRepository.Chemical chem=catalog.get(idx);JSONObject q=ix.forChemical(chem);drawChemicalCell(x,yy,cw,ch,idx+1,chemicalName(chem),q);}}}
        void overviewResultsOnly(JSONObject a){JSONArray arr=results(a);int pages=MIN_OVERVIEW_PAGES;for(int pg=0;pg<pages;pg++){newPage("خريطة النتائج • "+(pg+1)+"/"+pages);drawLegend();float left=20f,top=82f,cw=802f/GRID_COLS,ch=480f/GRID_ROWS;for(int slot=0;slot<GRID_CAPACITY;slot++){int idx=pg*GRID_CAPACITY+slot,row=slot/GRID_COLS,col=slot%GRID_COLS;float x=left+col*cw,yy=top+row*ch;JSONObject q=idx<arr.length()?arr.optJSONObject(idx):null;if(q==null)drawEmptyCell(x,yy,cw,ch);else drawChemicalCell(x,yy,cw,ch,idx+1,resultName(q),q);}}}
        void drawLegend(){float x=20f;legendChip(x,51,0xFFECEFF1,"لا دليل");x+=112;legendChip(x,51,0xFF90CAF9,"دليل غير كمي");x+=140;legendChip(x,51,0xFF43A047,"كمي/منخفض");x+=130;legendChip(x,51,0xFFF9A825,"تنبيه");x+=95;legendChip(x,51,0xFFEF6C00,"خطر");x+=90;legendChip(x,51,0xFFC62828,"حرج");}
        void legendChip(float x,float yy,int color,String label){p.setColor(color);c.drawRect(x,yy,x+14,yy+10,p);p.setColor(Color.DKGRAY);p.setTextAlign(Paint.Align.LEFT);p.setTextSize(7);c.drawText(label,x+18,yy+8,p);}
        void drawEmptyCell(float x,float yy,float w,float h){p.setColor(0xFFF7F8F9);c.drawRect(x,yy,x+w-1,yy+h-1,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(.5f);p.setColor(0xFFE0E3E6);c.drawRect(x,yy,x+w-1,yy+h-1,p);p.setStyle(Paint.Style.FILL);}
        void drawChemicalCell(float x,float yy,float w,float h,int index,String name,JSONObject q){boolean evidence=hasEvidence(q),quant=evidence&&q.optBoolean("quantitative",false);int risk=quant?q.optInt("risk",0):0;int bg=!evidence?0xFFECEFF1:!quant?0xFF90CAF9:risk>0?riskColor(risk):0xFF80CBC4;p.setColor(bg);c.drawRect(x,yy,x+w-1,yy+h-1,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(.6f);p.setColor(0xFFB0BEC5);c.drawRect(x,yy,x+w-1,yy+h-1,p);p.setStyle(Paint.Style.FILL);boolean dark=risk==1||risk==2||risk==5;p.setColor(dark?Color.WHITE:Color.rgb(40,40,40));p.setTextAlign(Paint.Align.CENTER);p.setTextSize(5.4f);c.drawText("#"+index,x+w/2,yy+8,p);p.setTextSize(5.7f);c.drawText(shortText(name,12),x+w/2,yy+19,p);p.setTextSize(5.5f);String value=!evidence?"—":quant?shortPpm(q):"دليل";c.drawText(value,x+w/2,yy+31,p);}

        void chemicals(JSONObject a){JSONArray arr=results(a);String[] h={"#","المركب","الصيغة","PPM","الثقة","الخطر"};float[] w={30,320,100,120,100,120};newPage("المركبات والغازات ذات الدليل");header(h,w);int shown=0;for(int i=0;i<arr.length();i++){JSONObject q=arr.optJSONObject(i);if(!hasEvidence(q))continue;if(y>560){newPage("المركبات والغازات ذات الدليل (تابع)");header(h,w);}shown++;boolean quant=q.optBoolean("quantitative",false);int risk=quant?q.optInt("risk",0):0;tableRow(new String[]{String.valueOf(shown),resultName(q),q.optString("formula",""),quant?num(q,"ppm"):"غير معتمد",stars(q.optInt("confidence",0)),risk>0?riskName(risk):"غير متاح"},w,risk);}if(shown==0)tableRow(new String[]{"—","لا توجد نتائج ذات دليل","","","",""},w,0);}
        void header(String[] v,float[] widths){p.setTextSize(9);float x=20;for(int i=0;i<v.length;i++){p.setColor(0xFF263238);c.drawRect(x,y,x+widths[i],y+20,p);p.setColor(Color.WHITE);p.setTextAlign(Paint.Align.CENTER);c.drawText(v[i],x+widths[i]/2,y+14,p);x+=widths[i];}y+=20;}
        void tableRow(String[] v,float[] widths,int risk){float x=20;int bg=riskColor(risk);for(int i=0;i<v.length;i++){p.setColor(i==v.length-1&&risk>0?bg:0xFFF5F7F8);c.drawRect(x,y,x+widths[i],y+18,p);p.setColor(i==v.length-1&&(risk==1||risk==2||risk==5)?Color.WHITE:Color.DKGRAY);p.setTextSize(8);p.setTextAlign(Paint.Align.CENTER);String t=v[i]==null?"":v[i];if(t.length()>42)t=t.substring(0,41)+"…";c.drawText(t,x+widths[i]/2,y+12,p);x+=widths[i];}y+=18;}
        void lineR(String s){p.setColor(Color.DKGRAY);p.setTextSize(11);p.setTextAlign(Paint.Align.RIGHT);c.drawText(s,812,y,p);y+=19;}
        void note(String s){p.setColor(0xFF455A64);p.setTextSize(9);p.setTextAlign(Paint.Align.RIGHT);String[] parts=s.split(" ");StringBuilder line=new StringBuilder();for(String word:parts){String test=line.length()==0?word:line+" "+word;if(p.measureText(test)>760){c.drawText(line.toString(),812,y,p);y+=15;line=new StringBuilder(word);}else{if(line.length()>0)line.append(' ');line.append(word);}}if(line.length()>0)c.drawText(line.toString(),812,y,p);y+=15;}
        void finish(){if(page!=null){pdf.finishPage(page);page=null;}}
    }

    private static JSONArray results(JSONObject a){JSONArray r=a==null?null:a.optJSONArray("results");return r==null?new JSONArray():r;}
    private static boolean hasEvidence(JSONObject q){return q!=null&&(q.optBoolean("evidence_present",false)||q.optInt("contributors",0)>0);}
    private static int resultCount(JSONObject a){JSONArray r=results(a);int n=0;for(int i=0;i<r.length();i++)if(hasEvidence(r.optJSONObject(i)))n++;return n;}
    private static String resultName(JSONObject q){if(q==null)return"";String ar=q.optString("name_ar","").trim();if(!ar.isEmpty())return ar;String name=q.optString("name","").trim();if(!name.isEmpty())return name;String en=q.optString("name_en","").trim();if(!en.isEmpty())return en;if(q.has("chemical_uid"))return"UID "+q.optLong("chemical_uid");if(q.has("chemical_id"))return"Chemical #"+q.optInt("chemical_id");return"مركب";}
    private static String chemicalName(ChemicalRepository.Chemical c){if(c==null)return"";String ar=c.arabicName==null?"":c.arabicName.trim();if(!ar.isEmpty())return ar;String en=c.name==null?"":c.name.trim();return en.isEmpty()?"UID "+c.uid:en;}
    private static String shortText(String s,int max){if(s==null)return"";String x=s.trim();return x.length()<=max?x:x.substring(0,Math.max(1,max-1))+"…";}
    private static String shortPpm(JSONObject q){double v=q==null?Double.NaN:q.optDouble("ppm",Double.NaN);if(!Double.isFinite(v))return"PPM —";return String.format(Locale.US,Math.abs(v)>=1000?"%.0f ppm":Math.abs(v)>=10?"%.1f ppm":"%.2f ppm",v);}
    private static JSONObject env(JSONObject d){JSONObject e=d.optJSONObject("env");return e!=null?e:d.optJSONObject("bme");}
    private static int riskStyle(int r){switch(r){case 1:return 2;case 2:return 3;case 3:return 4;case 4:return 5;case 5:return 6;default:return 7;}}
    private static int riskColor(int r){switch(r){case 1:return 0xFF1B5E20;case 2:return 0xFF43A047;case 3:return 0xFFF9A825;case 4:return 0xFFEF6C00;case 5:return 0xFFC62828;default:return 0xFF80CBC4;}}
    private static String riskName(int r){switch(r){case 1:return"آمن جدًا";case 2:return"آمن";case 3:return"تنبيه";case 4:return"خطر";case 5:return"حرج";default:return"غير متاح";}}
    private static String stars(int c){return c<=0?"—":c==1?"★☆☆":c==2?"★★☆":"★★★";}
    private static StringBuilder sheetStart(){return new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\" rightToLeft=\"1\"/></sheetViews><sheetData>");}
    private static String sheetEnd(StringBuilder s){return s.append("</sheetData></worksheet>").toString();}
    private static void row(StringBuilder s,int row,String[] values,int style){s.append("<row r=\"").append(row).append("\">");for(int i=0;i<values.length;i++)cell(s,col(i)+row,values[i],style);s.append("</row>");}
    private static void cell(StringBuilder s,String ref,String v,int style){s.append("<c r=\"").append(ref).append("\" t=\"inlineStr\"");if(style>0)s.append(" s=\"").append(style).append("\"");s.append("><is><t xml:space=\"preserve\">").append(xml(v)).append("</t></is></c>");}
    private static String col(int i){StringBuilder s=new StringBuilder();int n=i+1;while(n>0){int r=(n-1)%26;s.insert(0,(char)('A'+r));n=(n-1)/26;}return s.toString();}
    private static void entry(ZipOutputStream z,String name,String text)throws Exception{z.putNextEntry(new ZipEntry(name));z.write(text.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
    private static JSONObject json(String s){try{return s==null||s.trim().isEmpty()?new JSONObject():new JSONObject(s);}catch(Exception e){return new JSONObject();}}
    private static String num(JSONObject o,String key){if(o==null)return"";double v=o.optDouble(key,Double.NaN);return fmt(v);}
    private static String fmt(double v){if(!Double.isFinite(v))return"";return String.format(Locale.US,Math.abs(v)>=1000?"%.0f":Math.abs(v)>=10?"%.2f":"%.4f",v);}
    private static String n(String s){return s==null?"":s;}
    private static String xml(String s){if(s==null)return"";return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
}
